import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.D1JEzK2q.js";const g=JSON.parse('{"title":"Memory and knowledge","description":"","frontmatter":{},"headers":[],"relativePath":"guide/memory.md","filePath":"guide/memory.md"}'),d={name:"guide/memory.md"};function n(i,e,c,s,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="memory-and-knowledge" tabindex="-1">Memory and knowledge <a class="header-anchor" href="#memory-and-knowledge" aria-label="Permalink to &quot;Memory and knowledge&quot;">​</a></h1><p>Use core memory for information an agent should see every turn, and the searchable archive for detail it can retrieve when needed.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Use it for</th><th>How to inspect it</th></tr></thead><tbody><tr><td><code>MEMORY.md</code> and <code>USER.md</code></td><td>Durable facts and preferences</td><td>Read the workspace files</td></tr><tr><td>Per-agent archive</td><td>Longer notes outside the core budget</td><td>Ask for <code>memory_search</code> and <code>memory_get</code></td></tr><tr><td>Shared knowledge</td><td>Knowledge made available across agents</td><td>Dashboard Knowledge base tab</td></tr><tr><td>Chat history</td><td>Past conversations</td><td>Session history and history search</td></tr></tbody></table><h2 id="verify-recall" tabindex="-1">Verify recall <a class="header-anchor" href="#verify-recall" aria-label="Permalink to &quot;Verify recall&quot;">​</a></h2><p>Add a harmless project fact to a workspace note. Ask the agent to retrieve that specific fact and cite the source. Repeat in a new session to distinguish persistent recall from the current conversation&#39;s context. A plausible answer without a source is insufficient verification.</p><h2 id="control-the-budget" tabindex="-1">Control the budget <a class="header-anchor" href="#control-the-budget" aria-label="Permalink to &quot;Control the budget&quot;">​</a></h2><p>The template sets <code>gateway.memory.memoryBudgetChars</code> to <code>8000</code> and <code>userBudgetChars</code> to <code>3000</code>, with <code>overBudget: &quot;warn&quot;</code>. Archive notes that do not belong in the core context instead of increasing the budget indefinitely.</p><p><code>gateway.knowledge.archive</code> configures the SQLite/FTS5 searchable archive. <code>gateway.knowledge.shared</code> controls the shared knowledge location and mode. See the <a href="./../reference/configuration.html">configuration reference</a> before changing defaults.</p><h2 id="review-nightly-dreaming" tabindex="-1">Review nightly dreaming <a class="header-anchor" href="#review-nightly-dreaming" aria-label="Permalink to &quot;Review nightly dreaming&quot;">​</a></h2><p><code>gateway.dreaming</code> schedules background consolidation. The safe applier backs up memory and bounds changes; archived material can remain searchable after it leaves core memory. Inspect the dashboard&#39;s Nightly dreaming tab and the agent&#39;s <code>.dreaming/DREAMS.md</code> audit to understand a run.</p><p>Do not confuse history retention with memory consolidation. <code>gateway.history</code> and agent history overrides remove old chat/media records on their configured schedule; dreaming changes memory content.</p><p>Source: <a href="https://github.com/0xMaxMa/claude-gateway/blob/main/README.md#gatewaymemory" target="_blank" rel="noreferrer">memory, dreaming, and knowledge settings</a>.</p>',12)])])}const u=t(d,[["render",n]]);export{g as __pageData,u as default};
